function adjustViewport(){const e=window.innerWidth,t=document.querySelector('meta[name="viewport"]');if(e<375){const i=e/375;t.setAttribute("content",`width=375, initial-scale=${i}, maximum-scale=${i}, user-scalable=no`)}else t.setAttribute("content","width=device-width, initial-scale=1.0")}jQuery("#js-drawer-icon").on("click",function(e){e.preventDefault(),jQuery("#js-drawer-icon").toggleClass("is-checked"),jQuery("#js-drawer-content").toggleClass("is-checked")}),$("#js-drawer-content [href]").on("click",function(e){$("#js-drawer-icon").trigger("click")}),$('a[href^="#"]').on("click",function(){var e=$(this).attr("href"),t=$("#"==e||""==e?"html":e).offset().top;return $("html, body").animate({scrollTop:t},300,"swing"),!1}),window.addEventListener("load",adjustViewport),window.addEventListener("resize",adjustViewport);